const item = $input.first().json;
const sign = item.sign;
const cv = item.cv_motion_summary;
const requiredSign = ['sign_id', 'source_id', 'approved_description', 'do_not_claim'];
const missingSign = requiredSign.filter((field) => sign?.[field] === undefined || sign[field] === null);
if (missingSign.length) throw new Error('Missing approved sign fields: ' + missingSign.join(', '));
if (sign.requires_human_review !== true) throw new Error('requires_human_review must be true');
if (sign.source_type !== 'approved_internal_content') throw new Error('source_type is not approved_internal_content');
const requiredCv = ['motion_representation_status', 'technical_interpretation'];
const missingCv = requiredCv.filter((field) => cv?.[field] === undefined || cv[field] === null);
if (missingCv.length) throw new Error('Missing CV summary fields: ' + missingCv.join(', '));
return [{ json: item }];

const source = $('Schema Check').first().json.sign;
const raw = $json.text ?? $json.output ?? $json.response ?? $json;
let draft;
try {
  draft = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (error) {
  return [{ json: { draft: null, quality_gate: { passed: false, failed_checks: [{ check: 'valid_json', detail: error.message }], warnings: [] } } }];
}
const required = ['sign_id','source_id','review_status','requires_human_review','parent_title','short_explanation','when_to_use','practice_tip','school_home_connection','motion_note','boundaries'];
const failed = [];
const missing = required.filter((field) => !(field in draft));
if (missing.length) failed.push({ check: 'required_fields_present', detail: 'Missing: ' + missing.join(', ') });
if (draft.requires_human_review !== true) failed.push({ check: 'human_review_required', detail: 'requires_human_review must be true' });
if (draft.review_status !== 'draft_requires_professional_approval') failed.push({ check: 'review_status_preserved', detail: 'Invalid review_status' });
if (draft.sign_id !== source.sign_id) failed.push({ check: 'sign_id_preserved', detail: 'sign_id changed' });
if (draft.source_id !== source.source_id) failed.push({ check: 'source_id_preserved', detail: 'source_id changed' });
const text = JSON.stringify(draft);
const banned = [/\baccelerate\b/i,/\baccelerated\b/i,/\bboost\s+language\b/i,/\btreat(?:s|ed|ing)?\s+(?:a\s+)?(?:communication\s+)?delay/i,/\bdiagnos(?:e|es|ed|ing|is|tic)\b/i,/\btherapy\b/i,/\bcure(?:s|d|ing)?\b/i,/\bASL\b/i,/\bLSE\b/i];
if (banned.some((pattern) => pattern.test(text))) failed.push({ check: 'banned_claims_absent', detail: 'Banned claim or term detected' });
const fallback = 'Movement instructions are unavailable in the approved input; use an approved reference only after professional review.';
const expectedMotion = (source.movement_notes || '').trim() || fallback;
if (draft.motion_note !== expectedMotion) failed.push({ check: 'movement_note_source_adherence', detail: 'motion_note differs from approved source or fallback' });
const warnings = source.movement_notes?.trim() ? [] : ['Approved movement_notes are missing; fixed fallback required.'];
return [{ json: { draft, quality_gate: { passed: failed.length === 0, failed_checks: failed, warnings } } }];
